package main import ( "context" "fmt" "github.com/sufield/stave/pkg/stave" ) func main() { ctx := context.Background() // 1. Validate — structural check before evaluation vr, _ := stave.Validate(ctx, stave.ValidateConfig{ SnapshotsDir: "./observations", }) fmt.Printf("Valid: %v (%d controls, %d snapshots)
", vr.Valid, vr.ControlsChecked, vr.SnapshotsChecked) // 2. Evaluate — run the full control catalog assessment, _ := stave.Apply(ctx, stave.Config{ SnapshotsDir: "./observations", }) fmt.Printf("Status: %s, Findings: %d, Chains: %d
", assessment.Status, len(assessment.Findings), len(assessment.ChainFindings)) // 3. Score — compute posture score score, _ := stave.Score(ctx, stave.ScoreConfig{Assessment: assessment}) fmt.Printf("Posture: %.0f/100 (%s)
", score.Score, score.RubricBand) }
